def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda:f.read(1024*1024),b''):
            h.update(chunk)
    return h.hexdigest()

def matches(root, mapping):
    return all((root/rel).is_file() and digest(root/rel)==expected for rel,expected in mapping.items())

def main():
    root=Path.cwd()
    if not (root/'package.json').is_file() or not (root/'renderer/renderer.js').is_file():
        raise SystemExit('Run this installer from the NukeFire client repository beside package.json.')
    if matches(root, INSTALLED):
        print('Milestone 1.5b is already installed. Running verification...')
        result=subprocess.run(['npm','run','verify'],cwd=root)
        raise SystemExit(result.returncode)
    problems=[]
    for rel, expected in BASELINE.items():
        path=root/rel
        if not path.is_file(): problems.append(f'{rel} is missing')
        elif digest(path)!=expected: problems.append(f'{rel} does not match the confirmed 1.5a2 baseline')
    for rel in ADDED:
        path=root/rel
        if path.exists() and digest(path)!=INSTALLED[rel]: problems.append(f'{rel} already exists with unexpected content')
    if problems:
        print('Installer stopped without changing files:')
        for problem in problems: print(f'  - {problem}')
        print('\nReturn to milestone-1.5a2-styled-communications or use the full-source fallback.')
        raise SystemExit(2)
    backup=Path(tempfile.mkdtemp(prefix='nukefire-1.5b-backup-'))
    existed={}
    try:
        for rel in PAYLOAD:
            source=root/rel
            existed[rel]=source.exists()
            if source.exists():
                target=backup/rel
                target.parent.mkdir(parents=True,exist_ok=True)
                shutil.copy2(source,target)
        for rel, encoded in PAYLOAD.items():
            destination=root/rel
            destination.parent.mkdir(parents=True,exist_ok=True)
            data=gzip.decompress(base64.b64decode(encoded))
            temporary=destination.with_name(destination.name+f'.tmp-{os.getpid()}')
            temporary.write_bytes(data)
            os.replace(temporary,destination)
        if not matches(root, INSTALLED):
            raise RuntimeError('Installed file verification failed before tests.')
        print('Installed Milestone 1.5b files. Running npm run verify...')
        result=subprocess.run(['npm','run','verify'],cwd=root)
        if result.returncode:
            raise RuntimeError(f'npm run verify failed with exit code {result.returncode}')
    except Exception as error:
        print(f'Installation failed: {error}')
        print('Restoring the 1.5a2 files...')
        for rel, was_there in existed.items():
            destination=root/rel
            saved=backup/rel
            if was_there and saved.exists():
                destination.parent.mkdir(parents=True,exist_ok=True)
                shutil.copy2(saved,destination)
            elif not was_there:
                destination.unlink(missing_ok=True)
        raise SystemExit(1)
    finally:
        shutil.rmtree(backup,ignore_errors=True)
    print('\nMilestone 1.5b installed and verified successfully.')
    print('Start the client with: npm start')

if __name__=='__main__':
    main()
